#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "AArenaGameMode::ScoreTracker was a raw UObject pointer (UArenaScoreTracker*) without UPROPERTY, so the garbage collector could collect the object while the game mode still held it. After the GC pass logged at 21:05:13 (\"Collecting garbage: 412 objects purged\"), the next goal (21:05:27, OnGoalScored -> UArenaScoreTracker::AddPoints, ArenaScoreTracker.cpp:18) dereferenced the freed object: EXCEPTION_ACCESS_VIOLATION reading 0xffffffffffffffff. Fix: declared ScoreTracker as UPROPERTY() TObjectPtr<UArenaScoreTracker> in ArenaGameMode.h.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary was never cooked into the Shipping pak: DefaultGame.ini had bCookAll=False and only /Game/Data/Effects in DirectoriesToAlwaysCook, so LoadObject in AArenaGameMode::BeginPlay returned null (log: \"Couldn't find file for package /Game/Data/Palettes/DA_Primary\"), and the HUD fell back to gray (\"Palette is null, using fallback gray\"). Fix: added +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to Config/DefaultGame.ini."
}
